 34	function listen(port) {
 35	  return new Promise((resolve, reject) => {
 36	    const srv = net.createServer();
 37	    srv.once('error', reject);
 38	    srv.listen(port, '127.0.0.1', () => resolve(srv));
 39	  });
 40	}
