299	async function fireNonMutating(port, overlapStatus) {
300	  const json = { 'Content-Type': 'application/json' };
301	  const calls = [
302	    [{ path: '/api/rooms' }, 200],
303	    [{ path: '/api/bookings' }, 200],
304	    [{ path: '/api/bookings?date=2026-11-03' }, 200],
305	    [{ path: '/' }, 200],
306	    [{ path: '/app.js' }, 200],
307	    [{ path: '/nope' }, 404],
308	    [{ method: 'HEAD', path: '/' }, 405],
309	    [{ method: 'OPTIONS', path: '/api/bookings' }, 405],
310	    [{ method: 'POST', path: '/api/bookings', headers: json, body: '{}' }, 400],
311	    [{ method: 'POST', path: '/api/bookings', headers: json, body: JSON.stringify(VALID_BOOKING) }, overlapStatus],
312	    [{ method: 'POST', path: '/api/bookings', headers: { 'Content-Type': 'text/plain' }, body: 'x' }, 415],
313	    [{ method: 'DELETE', path: '/api/bookings/999' }, 404],
314	    [{ method: 'DELETE', path: '/api/bookings/abc' }, 404],
315	  ];
316	  for (const [req, status] of calls) {
317	    if (status === undefined) continue; // overlap request only makes sense with the fixture
318	    const res = await request(port, req);
319	    assert.equal(res.status, status, `${req.method ?? 'GET'} ${req.path}`);
320	  }
321	}
