    21	/** Runs fn(start) where start() launches a server on `file` and is tracked for cleanup. */
    22	async function withRuns(file, dir, fn) {
    23	  const running = [];
    24	  const start = async () => {
    25	    const server = await startServer({ env: { DATA_FILE: file }, cwd: dir });
    26	    running.push(server);
    27	    return server;
    28	  };
    29	  try {
    30	    return await fn(start);
    31	  } finally {
    32	    await Promise.all(running.map((s) => s.stop()));
    33	  }
    34	}
