   141	describe('concurrency', () => {
   142	  test('identical overlapping POSTs create exactly one booking', async () => {
   143	    await withTemp(async (dir) => {
   144	      const file = path.join(dir, 'data.json');
   145	      await withRuns(file, dir, async (start) => {
   146	        const { port } = await start();
   147	        const results = await Promise.all(Array.from({ length: 10 }, () => postBooking(port, VALID_BOOKING)));
   148	        const statuses = results.map((r) => r.status).sort();
   149	        assert.deepEqual(statuses, [201, ...Array(9).fill(409)]);
   150	        for (const r of results.filter((x) => x.status === 409)) assert.deepEqual(r.json(), OVERLAP_409);
   151	        assert.deepEqual(await list(port), { bookings: [expected(1, VALID_BOOKING)] });
   152	      });
   153	    });
   154	  });
