        assert.deepEqual(res.json(), { bookings: [morning, afternoon, late] });
        const created = await postBooking(server.port, { ...VALID_BOOKING, start: '16:00', end: '17:00' });
        assert.equal(created.status, 201);
        assert.equal(created.json().id, 10);
      });
    });
